+/** Theoretical sales use and all actual consumption per item over inclusive UTC days. */
+export function varianceReport(store, from, to) {
+  if (from > to) throw new AppError("bad_request", { reason: "from must be on or before to" });
+  const totals = new Map();
+  const add = (itemId, field, qty) => {
+    const line = totals.get(itemId) ?? { itemId, theoretical: 0, actual: 0 };
+    line[field] += Math.round(qty * 1000);
+    totals.set(itemId, line);
+  };
+  for (const sale of store.data.sales) {
+    const day = dayOf(sale.soldAt);
+    if (day < from || day > to) continue;
+    for (const ingredient of sale.ingredients) add(ingredient.itemId, "theoretical", ingredient.qty);
+  }
+  const batches = new Map(store.data.batches.map((batch) => [batch.id, batch.itemId]));
+  for (const movement of store.data.movements) {
+    if (movement.type !== "consume" || movement.qty <= 0) continue;
+    const day = dayOf(movement.at);
+    if (day < from || day > to || !batches.has(movement.batchId)) continue;
+    add(batches.get(movement.batchId), "actual", movement.qty);
+  }
+  return [...totals.values()]
+    .filter((line) => line.theoretical > 0 || line.actual > 0)
+    .sort((a, b) => a.itemId - b.itemId)
+    .map((line) => ({ itemId: line.itemId, theoretical: line.theoretical / 1000,
+      actual: line.actual / 1000, variance: (line.actual - line.theoretical) / 1000 }));
+}
