--- /dev/null
+++ b/src/io/sales-import.js
@@ -0,0 +1,42 @@
+import { AppError } from "../errors.js";
+import { parseCsv } from "./csv.js";
+import { importSales } from "../domain/sales.js";
+
+const HEADER = ["ticket", "soldAt", "dishId", "qty"];
+
+function invalid(row, reason) {
+  throw new AppError("sales_row", { row, reason });
+}
+
+/** Parses and validates a till CSV before importing the entire file atomically. */
+export function importSalesCsv(store, text) {
+  const lines = text.split(/\r?\n/);
+  const header = parseCsv(lines[0])[0] ?? [];
+  const keys = header.map((s) => s.trim());
+  if (keys.length !== HEADER.length || HEADER.some((key) => !keys.includes(key)))
+    invalid(1, "expected columns ticket,soldAt,dishId,qty");
+  const rows = [];
+  for (let i = 1; i < lines.length; i++) {
+    const line = lines[i];
+    if (!line.trim()) continue;
+    if (!/^(?:"(?:[^"]|"")*"|[^",]*)(?:,(?:"(?:[^"]|"")*"|[^",]*))*$/.test(line))
+      invalid(i + 1, "malformed CSV");
+    const fields = parseCsv(line)[0];
+    if (fields.length !== keys.length) invalid(i + 1, "wrong number of fields");
+    const row = Object.fromEntries(keys.map((key, index) => [key, fields[index].trim()]));
+    if (!row.ticket) invalid(i + 1, "ticket is required");
+    const instant = /^(\d{4}-\d{2}-\d{2})T(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d+)?(?:Z|[+-](?:[01]\d|2[0-3]):[0-5]\d)$/;
+    if (!instant.test(row.soldAt) || !Number.isFinite(Date.parse(row.soldAt)) ||
+        new Date(`${row.soldAt.slice(0, 10)}T00:00:00Z`).toISOString().slice(0, 10) !== row.soldAt.slice(0, 10))
+      invalid(i + 1, "soldAt must be an ISO instant");
+    const dishId = Number(row.dishId);
+    const qty = Number(row.qty);
+    if (!/^\d+$/.test(row.dishId) || !Number.isSafeInteger(dishId) || dishId < 1)
+      invalid(i + 1, "dishId must be a positive integer");
+    if (!/^\d+$/.test(row.qty) || !Number.isSafeInteger(qty) || qty < 1)
+      invalid(i + 1, "qty must be a positive integer");
+    if (!store.data.dishes.some((dish) => dish.id === dishId)) invalid(i + 1, "unknown dish");
+    rows.push({ ticket: row.ticket, soldAt: new Date(row.soldAt).toISOString(), dishId, qty, row: i + 1 });
+  }
+  return importSales(store, rows);
+}
